import csv
import sys

def main():
    if len(sys.argv) < 2:
        print("Error: Please provide the CSV file path as a command-line argument.")
        sys.exit(1)

    filepath = sys.argv[1]

    try:
        with open(filepath, newline='') as f:
            reader = csv.reader(f)
            headers = next(reader, None)  # Read the header row
            if headers is None:
                print("Error: The CSV file is empty (no header row).")
                sys.exit(1)

            rows = list(reader)
    except FileNotFoundError:
        print(f"Error: File '{filepath}' not found.")
        sys.exit(1)
    except Exception as e:
        print(f"Error reading file: {e}")
        sys.exit(1)

    num_rows = len(rows)
    num_cols = len(headers)

    print(f"Number of rows (excluding header): {num_rows}")
    print(f"Number of columns: {num_cols}")
    print(f"Column names: {', '.join(headers)}")

    # Collect data per column
    col_data = {header: [] for header in headers}
    for row in rows:
        for i, header in enumerate(headers):
            if i < len(row):
                col_data[header].append(row[i])
            else:
                col_data[header].append('')  # treat missing as empty

    # Identify numeric columns and compute stats
    for i, header in enumerate(headers):
        values = col_data[header]
        # Try to convert all non-empty values to float
        numeric_values = []
        for v in values:
            v = v.strip()
            if v == '':
                continue
            try:
                numeric_values.append(float(v))
            except ValueError:
                numeric_values = None
                break

        if numeric_values is not None and len(numeric_values) > 0:
            min_val = min(numeric_values)
            max_val = max(numeric_values)
            mean_val = sum(numeric_values) / len(numeric_values)
            print(f"Column '{header}' (numeric): min={min_val}, max={max_val}, mean={mean_val}")
        else:
            if numeric_values is None:
                print(f"Column '{header}': non-numeric")
            else:
                print(f"Column '{header}': empty (no data)")

if __name__ == "__main__":
    main()
